/*
 * This file was generated by the Gradle 'init' task.
 *
 * This generated file contains a sample Java application project to get you started.
 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/9.8.0/userguide/building_java_projects.html in the Gradle documentation.
 */

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
    java
    id("com.gradleup.shadow") version "9.6.1"
}

val appVersion = providers.gradleProperty("appVersion").getOrElse("0.0.0-dev")
version = appVersion

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit Jupiter for testing.
    testImplementation(libs.junit.jupiter)

    testRuntimeOnly("org.junit.platform:junit-platform-launcher")

    // This dependency is used by the application.
    implementation(libs.guava)
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(27)
    }
}

application {
    // Define the main class for the application.
    mainClass = "net.froglux.App"
}

tasks.jar {
    archiveFileName.set("bps.jar")
    manifest {
        attributes (
            "Main-Class" to "net.froglux.App",
            "Implementation-Version" to appVersion
        )
    }
}

tasks.shadowJar {
    archiveFileName.set("bps-all.jar")
}

tasks.named("assemble") {
    dependsOn(tasks.shadowJar)
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
}
